import type { CreatureKind, Severity } from "@haunted/core";
import meta from "@/public/sprites/sprites.json";

export interface SpriteSheet {
  w: number;
  h: number;
  sheet: string;
}

type Meta = Record<string, { frame_w: number; frame_h: number; frames: number; sheet: string }>;

/** All sheets from public/sprites/sprites.json (generated by tools/sprites/make.py, 6x scale). */
export const SPRITES: Partial<Record<CreatureKind, SpriteSheet>> = Object.fromEntries(
  Object.entries(meta as Meta).map(([k, m]) => [k, { w: m.frame_w, h: m.frame_h, sheet: `/sprites/${m.sheet}` }]),
);

/** Size of the placeholder box at scale 1, close to the real sprites. */
export const PLACEHOLDER_SIZE = 100;

/** Creature size shows severity (product.md). */
export const SEVERITY_SCALE: Record<Severity, number> = { critical: 1, warning: 0.8, low: 0.6 };

export interface KindCopy {
  one: string;
  many: string;
  /** Counter label in the house, singular noun. */
  short: string;
  /** Subtitle on cards: what the creature stands for. */
  meaning: string;
  description: string;
  fixLine: string;
  glyph: string;
  /** Animation word on bestiary cards. */
  motion: string;
}

